export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:10。M 區。走廊。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部站在走廊中間。他的面前放著一台筆電。螢幕上是活動接收者依存狀態面板。他沒有碰鍵盤。他在等兩組各自就位。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "紅區評估。程序如下。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "系統安全組和外部醫療組——獨立評估。不交叉。不討論。系統組判參照依存級別、本地備援狀態、閉環斷開後的訊號結果。外部醫療組判自然故障時的生理資料、腦電、呼吸、自律神經、藥物、意識、中斷風險。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "只有兩組均判定中斷具有不可接受、不可逆風險——才列入紅區下限。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看了一眼外部醫師。外部醫師點頭。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "外部醫療組接受。獨立評估。不接觸系統組資料。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家也點頭。他的螢幕上已經打開了依存圖的離線副本。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "開始。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:15。兩組同時開始。系統安全組在左。外部醫療組在中間。各自面對各自的螢幕和表格。中間隔著三公尺。看不到彼此。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在走廊盡頭。她看不到任何一組的螢幕。但她能聽到聲音。零散的。片段的。鍵盤。列印。低聲確認。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:25。系統安全組的螢幕上開始出現結果。指定專家的手指停在鍵盤上。他看著螢幕。然後他叫了千田。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "G07／12。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上。一個接收者條目。狀態欄。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "G07／12——SAFE／DETACHED。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "悠真。已完成外部醫療及參照安全切離。不在閉環裡了。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田的聲音很平。但他的肩膀鬆了一點。只有一點。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）悠真。SAFE。DETACHED。他不在閉環裡了。他安全了。至少——在系統層面——他安全了。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:30。系統安全組繼續往下。其他活動單元的狀態開始出現。不是 SAFE。不是 DETACHED。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "ACTIVE。REMOTE CAL。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "一個。又一個。又一個。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上的列表在延伸。大部分條目顯示 ACTIVE／REMOTE CAL。有些顯示 ACTIVE／LOCAL CAL。少數顯示 LEGACY／REMOTE CAL。沒有名字。只有代碼。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "依存級別分三檔——高依存、中依存、低依存。高依存定義為——閉環中斷後無本地備援或本地影子參照不完整。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:40。外部醫療組也在出結果。外部醫師的夾板上多了好幾頁。每一頁對應一個活動單元。每一頁上有腦電摘要、呼吸頻率、自律神經波動、藥物清單、意識等級。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到其中一頁。停了。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "13.4 秒自然故障時——呼吸頻率從十八升至三十一。自律神經嚴重波動。腦電出現異常放電。本地影子參照不完整。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到另一頁。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "另一場既有切換事件——長時間癲癇樣放電。無完整本地影子參照。中斷風險不可接受。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有說名字。他只說代碼。因為他看不到名字。他的表格上只有代碼。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:50。兩組各自完成初步評估。日下部走到走廊中間。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "交叉比對。系統組先報高依存。醫療組再報中斷風險。只有兩組都判高風險的——列入紅區。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指定專家念出系統組的高依存清單。四個代碼。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.DesignatedExpert, character: "指定專家", dialogue: "M-00、G07／03、高依存遠端單元 B、LEGACY／02。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師翻到對應頁面。一個一個核對。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "M-00——高度依賴雙向閉環。硬切可能造成死亡、深度昏迷或不可逆神經崩潰。中斷風險不可接受。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到下一頁。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "G07／03——13.4 秒自然故障時呼吸、自律與腦電嚴重波動。本地影子參照不完整。外部神經醫師判定硬切風險不可接受。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "下一頁。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "高依存遠端單元 B——歷史切換時長時間癲癇樣放電。無完整本地影子參照。中斷風險不可接受。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "下一頁。他停了一下。他看了一眼那個代碼。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "LEGACY／02。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他翻到對應頁面。看了幾秒。然後他抬起頭。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "LEGACY／02——唯一穩定源仍為 M-00。本地模型已退役。過去失去參照後出現長時間失語及意識障礙。中斷風險不可接受。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。然後他加了一句。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "標記——HUMAN。不是設備。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡安靜了一瞬。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "日下部在表格上寫了四行。每行一個代碼。每行後面標著——紅區。HUMAN。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "四個紅區下限。系統組與外部醫療組獨立評估。均跨越不可逆嚴重傷害門檻。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他放下筆。看著那四行。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "M-00。G07／03。高依存遠端單元 B。LEGACY／02。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "四個代碼。四個活人。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:00。千田走到日下部旁邊。他看了一眼表格。然後他看了一眼螢幕上的依存圖。他的手指停在 G07／03 那一行。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "G07／03。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有說名字。他只說代碼。但他的聲音變了一點。不是更重。是更慢。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "身體不在筑波。已由外部醫療機構接管。物理轉移完成。醫療接管完成。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停了一下。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "但參照安全切離——未完成。本地影子參照不完整。神經與醫療校準仍掛在 M-00／KAGAMI 共用閉環上。REMOTE CAL ACTIVE。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在走廊盡頭。她聽到了。不是全部。但「不在筑波」和「REMOTE CAL ACTIVE」她聽到了。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不在筑波。身體已經離開了。可是還在系統裡。什麼意思。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:05。日下部把三種撤離的定義寫在白板上。他的字很工整。像在寫公文。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "物理轉移——人已離開原研究設施。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "醫療接管——人已由外部醫療或法定程序控制。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "參照安全切離——人已不再依賴 M-00／KAGAMI 共用閉環。改由本地影子參照或其他安全方案接管。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在第三行底下畫了一條線。寫了一行。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "未撤離者——指第三種尚未完成。不是身體仍在筑波。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "千田看著白板。他點了一下頭。然後他轉過身。他看向走廊盡頭。看向澪。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他走過去。站在澪面前。他的聲音不高。但走廊很安靜。所有人都聽到了。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "G07／03。身體早已離開筑波。已在普通醫療機構。物理轉移完成。醫療接管完成。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "可是本地影子參照尚未完成。神經與醫療校準仍掛在共用系統上。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯她不在筑波了。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.ChidaKosuke, character: "千田浩介", dialogue: "但她還沒有從系統裡出去。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.ChidaKosuke_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪看著他。他的臉很疲憊。但他的眼睛沒有閃避。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）不在筑波。身體在外面。在普通醫院。可是系統還在校準她。還在用她。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡的鍵盤聲停了。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她還是活動接收者。身體離開了——系統沒有放開。未撤離——不是身體還在設施裡。是參照還掛著。是影子還沒長出來。是閉環還沒斷開。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:15。日下部在白板上補了最後一行。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "四個紅區。均為 HUMAN。均為活人。均跨所有合理參數組合進入不可逆嚴重傷害門檻。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他轉過身。看著所有人。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.KusakubeSatoru, character: "日下部悟", dialogue: "不寫死亡數。不寫「一定死」。寫——在所有合理情境中，以上四名活動接收者均跨越不可逆嚴重傷害門檻。部分情境包含死亡。其他活動單元亦有風險，但無法建立同樣穩定的下限。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.KusakubeSatoru_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師在表格上簽名。指定專家在表格上簽名。兩組獨立簽名。兩組獨立結論。同一個結果。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:10。系統安全組的依存狀態面板自己捲到最底。不是人填的。系統把所有條目算完，吐出一塊總計。日下部的目光停在那塊螢幕上。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他沒有念名字。他把總計念出來——讓走廊裡的人都聽到。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text TOTAL HUMAN RECORDS          9 SAFE-DETACHED                1／G07-12／悠真 ACTIVE HUMAN DEPENDENCIES    8 CRITICAL RED-ZONE            4 OTHER ACTIVE                 4 ```", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "九筆活人紀錄。一名已安全切離。八名仍掛在共用閉環上。其中四名——剛簽下的紅區。另外四名——有風險，下限還沒站穩。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）九。一。八。四。四。澪坐在走廊盡頭。她看不到那塊螢幕。可日下部把數字念了出來——她聽到了。她記下了。她還不知道這些數字後來會變成什麼。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:20。澪站起來。她走到白板前。她看著那四行代碼。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "M-00。她知道是誰。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "G07／03。她還不知道是誰。只知道不在筑波。只知道還在系統裡。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "高依存遠端單元 B。姓名依法遮蔽。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "LEGACY／02。HUMAN。不是設備。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）四個人。四個活人。如果硬切——他們會被寫成代價。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的目光停在白板上那四行代碼上。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）母親在其中。還有三個人。兩個是未成年人。一個連名字都還被遮著。可是他們都是人。不是代碼。不是參數。不是「必要的犧牲」。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她伸出手。她的手指碰了一下白板上 M-00 那一行。沒有用力。只是碰了一下。像在確認它真的在那裡。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後她收回手。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）母親。如果 R4 被執行——母親可能死。可能再也醒不過來。可能永遠失去剛恢復的語言和意識。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "指尖還留著一點白板上的粉筆灰。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）未來的我知道這些。她知道 M-00 是母親。她還是接受了。一次。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:25。日下部把白板上的內容拍下來。封存。編號。簽名。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡的人開始收拾。系統安全組合上筆電。外部醫療組把夾板收進資料袋。午休時間到了。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪沒有動。她站在白板前。看著那四行代碼。四個活人。四個還沒有從系統裡出去的人。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）未撤離者。不是身體還在筑波。是參照還掛著。是閉環還沒斷。是影子還沒長出來。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "走廊裡的腳步聲開始鬆散。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）身體可以搬走。醫療可以接管。可是系統不放——人就不算離開。這就是「未撤離」。這就是母親和那三個人現在的狀態。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "白板上的四行代碼在走廊盡頭的光線裡微微反光。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）身體在外面。系統在裡面。中間——是一條還沒有被切斷的線。", background: Background.Chapter_22_Ch22_Act3_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:30。走廊。螢光燈。呼吸器的節奏從觀察窗後面傳過來。很慢。", background: Background.Chapter_22_Ch22_Act3_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約三日十七小時四十三分鐘。", background: Background.Chapter_22_Ch22_Act3_S0 },
];
